// MsgServer is the server API for Msg service.
type MsgServer interface {
	// LockTokens locks tokens on AURA for transfer to PAW or XAI
	LockTokens(context.Context, *MsgLockTokens) (*MsgLockTokensResponse, error)
	// MintTokens mints wrapped tokens on AURA from PAW or XAI (validator-only)
	MintTokens(context.Context, *MsgMintTokens) (*MsgMintTokensResponse, error)
	// UnlockTokens unlocks tokens on AURA after burn proof from target chain
	UnlockTokens(context.Context, *MsgUnlockTokens) (*MsgUnlockTokensResponse, error)
	// BurnTokens burns wrapped tokens on AURA to unlock on source chain
	BurnTokens(context.Context, *MsgBurnTokens) (*MsgBurnTokensResponse, error)
	// LinkAddress links addresses across chains for shared identity
	LinkAddress(context.Context, *MsgLinkAddress) (*MsgLinkAddressResponse, error)
	// CrossChainSwap initiates cross-chain swap
	CrossChainSwap(context.Context, *MsgCrossChainSwap) (*MsgCrossChainSwapResponse, error)
	// RelayTransfer relays cross-chain transfer (relayer-only)
	RelayTransfer(context.Context, *MsgRelayTransfer) (*MsgRelayTransferResponse, error)
	// FinalizeTransfer finalizes a pending transfer after fraud proof window
	FinalizeTransfer(context.Context, *MsgFinalizeTransfer) (*MsgFinalizeTransferResponse, error)
	// SubmitFraudProof challenges a fraudulent transfer during the window
	SubmitFraudProof(context.Context, *MsgSubmitFraudProof) (*MsgSubmitFraudProofResponse, error)
}

